-- Enrichment Batch 36 (2026-10-29): NEW 1002 UBC Okanagan Global Elevation Award + 1003 UBC
-- Okanagan International Welcome Award (both rel 10, from sources 3154/3155 fetched first-hand
-- in Batch 34); micro-update 356 (deadline_date 2026-11-15 + status open + link 455 to the
-- dates page); us rows 719/720; links 451-455. No new sources. The third Okanagan award on
-- the page (BCom Launch, CAD 6,000) deliberately not catalogued (single-degree/Sept-2027
-- framing, recurrence unestablished). CTU probe: host still unavailable, no writes.
-- Notes appends are replay-once.

-- 1) Micro-update 356 (International Scholars Program current-cycle date)
UPDATE scholarships SET deadline_date = '2026-11-15', application_status = 'open', expected_opening_period = 'Early October each year (5 October 2026 for September 2027 entry)', last_verified_at = '2026-10-29 23:00:00+05', last_updated_at = '2026-10-29 23:00:00+05', notes = COALESCE(notes, '') || ' Batch 36 micro-update (2026-10-29): the current cycle''s operative date is now stored structurally — deadline_date 2026-11-15 and status open (this record''s own verified text already stated that applications for September 2027 entry opened on 5 October 2026 with nominator/referee recommendations due just before 15 November; UBC''s dates-and-deadlines page, source 3155 fetched first-hand in Batch 34 and linked today, gives the same 15 November 2026, 11:59 p.m. PST deadline for applying to UBC and submitting the International Scholars award application). No terms changed.' WHERE id = 356;

-- 2) NEW 1002 + 1003 (UBC Okanagan automatic awards)
INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, degree_levels, eligible_majors, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, eligible_countries, funding_type, tuition_coverage, living_allowance, travel_allowance, accommodation, application_fee, english_requirements, required_documents, application_url, opening_date, deadline_date, deadline_type, deadline_range_start, deadline_range_end, rounds, recurrence, expected_opening_period, expected_deadline_period, application_status, last_verified_at, last_updated_at, verification_status, source_reliability, source_url, notes, is_active, university_id, award_amount, award_currency, award_period, award_basis) VALUES
(1002, 'UBC Okanagan Global Elevation Award', 'University of British Columbia (Okanagan campus)', 'Canada', 'Partial Tuition', 0, 'No separate application — the award is applied automatically as a tuition credit once a new international undergraduate enrols at UBC Okanagan and accepts the offer of admission. The operative date is the UBC application deadline (15 January 2027, 11:59 p.m. PST, for September 2027 entry).', '["Bachelor''s"]', '["All Majors"]', NULL, NULL, false, false, 'The UBC Okanagan Global Elevation Award is an automatic CAD 8,000-per-year tuition credit for international students at UBC''s Okanagan campus in Kelowna. UBC states that all new international undergraduate students who enrol at UBC Okanagan receive it: it is renewable for an additional three years (up to four years or degree completion, whichever is sooner) and is paid as two equal instalments of CAD 4,000 in Winter Term 1 and Winter Term 2. There is no competition and no separate application — if you are accepted to and enrol at UBC Okanagan, the credit is applied to your student account after you accept the offer of admission. UBC presents it as a way to reward international students who choose the Okanagan campus and contribute to the growth of its international community; it sits alongside the competitive Vancouver-campus entrance awards (IMES, record 602; OIS, record 994) and the Okanagan International Welcome Award (record 1003), and as a partial credit it does not cover the full cost of a degree.', 'Be a new international student who enrols in an undergraduate programme at UBC Okanagan — that is the only eligibility condition UBC publishes for this award. It is applied automatically after you accept UBC''s offer of admission, so the practical requirements are upstream: apply to UBC by the admissions deadline, be admitted to a UBC Okanagan programme, meet the programme''s admission requirements and UBC''s English Language Admission Standard, accept the offer and enrol. No GPA or IELTS scholarship cutoff is published for the award itself.', 'https://you.ubc.ca/financial-planning/scholarships-awards-international-students/', '["All"]', 'Automatic tuition credit (non-competitive)', 'CAD 8,000 per year credited against tuition (two CAD 4,000 instalments in Winter Term 1 and Winter Term 2), renewable for up to three additional years or until degree completion, whichever is sooner.', NULL, NULL, NULL, NULL, 'No scholarship-specific English score is published; applicants must meet UBC''s English Language Admission Standard (ELAS) for their programme (ELAS documents are due by 15 February 2027 in the current cycle).', '["UBC admission application (no separate scholarship form)","Transcripts and other documents UBC requires for admission","Evidence of English language competency under UBC''s English Language Admission Standard"]', 'https://you.ubc.ca/apply/', NULL, '2027-01-15', 'automatic', NULL, NULL, '[]', 'annual', 'Early October each year (UBC online application opens for the next Winter Session)', 'Mid-January each year (UBC application deadline; 15 January 2027 for September 2027 entry)', 'open', '2026-10-29 23:00:00+05', '2026-10-29 23:00:00+05', 'verified', 10, 'https://you.ubc.ca/financial-planning/scholarships-awards-international-students/', 'NEW in Enrichment Batch 36 (2026-10-29), written from the first-hand read of UBC''s official "Scholarships and awards for international students" page and dates-and-deadlines page (sources 3154/3155, fetched 2026-10-29 during Batch 34, when the Okanagan awards were noted but deferred). deadline_date stores the operative UBC application deadline (15 January 2027) because the award itself is automatic on enrolment; the application opened in early October 2026, hence status=open. The amount is a single published figure, stored as CAD 8,000 / year / fixed. Whether this credit stacks with the Okanagan International Welcome Award (record 1003) is not stated on the page read and is not claimed here. The third Okanagan award on the same page (Bachelor of Commerce International Launch Award, CAD 6,000) was not catalogued: the page frames it for the September 2027 intake of one degree, so its recurrence is not established.', true, 49, 8000, 'CAD', 'year', 'fixed'),
(1003, 'UBC Okanagan International Welcome Award', 'University of British Columbia (Okanagan campus)', 'Canada', 'Partial Tuition', 0, 'No separate application — the award is applied automatically as a first-year tuition credit to international students who list a UBC Okanagan degree as their first choice, are accepted and enrol in that first-choice programme. The operative date is the UBC application deadline (15 January 2027, 11:59 p.m. PST, for September 2027 entry).', '["Bachelor''s"]', '["All Majors"]', NULL, NULL, false, false, 'The UBC Okanagan International Welcome Award is an automatic CAD 5,000 credit against first-year tuition at UBC''s Okanagan campus. Every international student who applies to UBC with a UBC Okanagan degree as their first choice and who is accepted into and enrols in that first-choice programme receives it for the first year of full-time study: 50 percent is applied to Term 1 tuition and 50 percent to Term 2, provided the student stays enrolled in a minimum number of credits, and the credit appears on the Applicant Service Centre account once classes start in September. There is no scholarship form and no competition — the first-choice condition in the admission application is what triggers it. It is one of the automatic Okanagan campus awards UBC lists next to the competitive entrance scholarships, and as a one-year partial credit it does not cover the full cost of a degree.', 'To receive the award you must: be a first-year international student enrolled in a full-time course load (24 credits in the Winter Session); select a UBC Okanagan degree as your first choice in the UBC application; and be accepted to UBC Okanagan and enrol into that first-choice degree. The credit is then applied automatically after you accept the offer of admission. Upstream of that, you must apply by the UBC admissions deadline and meet your programme''s admission requirements and UBC''s English Language Admission Standard. No GPA or IELTS scholarship cutoff is published for the award itself.', 'https://you.ubc.ca/financial-planning/scholarships-awards-international-students/', '["All"]', 'Automatic tuition credit (non-competitive)', 'CAD 5,000 credited against first-year tuition only (50 percent in Term 1 and 50 percent in Term 2, while enrolled in a minimum number of credits); not renewable.', NULL, NULL, NULL, NULL, 'No scholarship-specific English score is published; applicants must meet UBC''s English Language Admission Standard (ELAS) for their programme (ELAS documents are due by 15 February 2027 in the current cycle).', '["UBC admission application with a UBC Okanagan degree listed as first choice (no separate scholarship form)","Transcripts and other documents UBC requires for admission","Evidence of English language competency under UBC''s English Language Admission Standard"]', 'https://you.ubc.ca/apply/', NULL, '2027-01-15', 'automatic', NULL, NULL, '[]', 'annual', 'Early October each year (UBC online application opens for the next Winter Session)', 'Mid-January each year (UBC application deadline; 15 January 2027 for September 2027 entry)', 'open', '2026-10-29 23:00:00+05', '2026-10-29 23:00:00+05', 'verified', 10, 'https://you.ubc.ca/financial-planning/scholarships-awards-international-students/', 'NEW in Enrichment Batch 36 (2026-10-29), written from the first-hand read of UBC''s official "Scholarships and awards for international students" page and dates-and-deadlines page (sources 3154/3155, fetched 2026-10-29 during Batch 34, when the Okanagan awards were noted but deferred). deadline_date stores the operative UBC application deadline (15 January 2027) because the award is automatic for first-choice Okanagan enrollees; the application opened in early October 2026, hence status=open. The amount is a single published figure, stored as CAD 5,000 / one_time / fixed (first year only, two instalments). Whether it stacks with the Global Elevation Award (record 1002) is not stated on the page read and is not claimed here.', true, 49, 5000, 'CAD', 'one_time', 'fixed');

