-- 4) Side rows 719/720 (UBC = university 49)
INSERT INTO university_scholarships (id, university_id, scholarship_id, scholarship_name, availability_status, funding_type, max_scholarship, covers_tuition, covers_living_expenses, valued_aspect, eligibility_notes, official_url, source_url, verification_status, last_verified_at) VALUES
(719, 49, 1002, 'UBC Okanagan Global Elevation Award', 'available', 'Automatic tuition credit', 'CAD 8,000 per year, renewable up to 4 years (two CAD 4,000 instalments per year)', true, false, 'Automatic for all new international enrollees at UBC Okanagan', 'Every new international undergraduate who enrols at UBC Okanagan receives this credit automatically after accepting the offer (apply to UBC by 15 January 2027 for September 2027 entry); no separate application, no published GPA/IELTS cutoff (UBC''s English Language Admission Standard applies).', 'https://you.ubc.ca/financial-planning/scholarships-awards-international-students/', 'https://you.ubc.ca/financial-planning/scholarships-awards-international-students/', 'verified', '2026-10-29 23:00:00+05'),
(720, 49, 1003, 'UBC Okanagan International Welcome Award', 'available', 'Automatic tuition credit', 'CAD 5,000 first-year tuition credit (50% Term 1, 50% Term 2)', true, false, 'First-choice commitment to a UBC Okanagan degree', 'Automatic for international students who list a UBC Okanagan degree as first choice, are accepted and enrol full-time (24 credits) in that programme (apply to UBC by 15 January 2027 for September 2027 entry); first year only; no published GPA/IELTS cutoff (UBC''s English Language Admission Standard applies).', 'https://you.ubc.ca/financial-planning/scholarships-awards-international-students/', 'https://you.ubc.ca/financial-planning/scholarships-awards-international-students/', 'verified', '2026-10-29 23:00:00+05');

